package bo.com.ganadero.sanidad.infrastructure;import bo.com.ganadero.sanidad.domain.*;import bo.com.ganadero.shared.error.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Repository;import java.sql.*;import java.time.*;import java.util.*;
@Repository public class JdbcClinicaRepository implements ClinicaRepository{private final JdbcClient j;public JdbcClinicaRepository(JdbcClient j){this.j=j;}
public CasoClinico crearCaso(CasoClinico c,UUID a){j.sql("insert into sanidad.casos_clinicos(id,empresa_id,animal_id,fecha_inicio,sintomas,enfermedad_id,diagnostico_texto,severidad,estado,veterinario_id,observaciones,created_by,updated_by) values(:id,:e,:an,:f,:s,:enf,:d,:sev,:est,:v,:o,:a,:a)").param("id",c.id()).param("e",c.empresaId()).param("an",c.animalId()).param("f",ts(c.fechaInicio())).param("s",c.sintomas()).param("enf",c.enfermedadId()).param("d",c.diagnosticoTexto()).param("sev",c.severidad().name()).param("est",c.estado().name()).param("v",c.veterinarioId()).param("o",c.observaciones()).param("a",a).update();return caso(c.id(),c.empresaId()).orElseThrow();}
public Optional<CasoClinico>caso(UUID id,UUID e){return j.sql("select * from sanidad.casos_clinicos where id=:id and empresa_id=:e").param("id",id).param("e",e).query(this::mc).optional();}public List<CasoClinico>casos(UUID e,UUID a){return j.sql("select * from sanidad.casos_clinicos where empresa_id=:e and (cast(:a as uuid) is null or animal_id=:a) order by fecha_inicio desc").param("e",e).param("a",a).query(this::mc).list();}
public void estadoCaso(UUID id,UUID e,EstadoCasoClinico s,Instant f,String r,UUID a){j.sql("update sanidad.casos_clinicos set estado=:s,fecha_cierre=:f,resultado=:r,updated_at=now(),updated_by=:a,version=version+1 where id=:id and empresa_id=:e").param("s",s.name()).param("f",ts(f)).param("r",r).param("a",a).param("id",id).param("e",e).update();}
public Tratamiento crearTratamiento(Tratamiento t,UUID a){j.sql("insert into sanidad.tratamientos(id,empresa_id,caso_clinico_id,animal_id,fecha_inicio,fecha_fin_estimada,diagnostico,veterinario_id,estado,observaciones,created_by,updated_by) values(:id,:e,:c,:an,:ini,:fin,:d,:v,:s,:o,:a,:a)").param("id",t.id()).param("e",t.empresaId()).param("c",t.casoClinicoId()).param("an",t.animalId()).param("ini",ts(t.fechaInicio())).param("fin",ts(t.fechaFinEstimada())).param("d",t.diagnostico()).param("v",t.veterinarioId()).param("s",t.estado().name()).param("o",t.observaciones()).param("a",a).update();return tratamiento(t.id(),t.empresaId()).orElseThrow();}
public Optional<Tratamiento>tratamiento(UUID id,UUID e){return j.sql("select * from sanidad.tratamientos where id=:id and empresa_id=:e").param("id",id).param("e",e).query(this::mt).optional();}public List<Tratamiento>tratamientos(UUID e,UUID a){return j.sql("select * from sanidad.tratamientos where empresa_id=:e and (cast(:a as uuid) is null or animal_id=:a) order by fecha_inicio desc").param("e",e).param("a",a).query(this::mt).list();}
public TratamientoDetalle crearDetalle(TratamientoDetalle d){j.sql("insert into sanidad.tratamiento_detalles(id,empresa_id,tratamiento_id,producto_id,lote_producto_id,dosis,unidad_dosis,frecuencia_horas,duracion_dias,via_administracion,retiro_carne_dias,retiro_leche_dias) values(:id,:e,:t,:p,:lp,:d,:u,:f,:dur,:v,:rc,:rl)").param("id",d.id()).param("e",d.empresaId()).param("t",d.tratamientoId()).param("p",d.productoId()).param("lp",d.loteProductoId()).param("d",d.dosis()).param("u",d.unidadDosis()).param("f",d.frecuenciaHoras()).param("dur",d.duracionDias()).param("v",d.viaAdministracion()).param("rc",d.retiroCarneDias()).param("rl",d.retiroLecheDias()).update();return d;}public List<TratamientoDetalle>detalles(UUID t,UUID e){return j.sql("select * from sanidad.tratamiento_detalles where tratamiento_id=:t and empresa_id=:e").param("t",t).param("e",e).query(this::md).list();}
public AplicacionTratamiento crearAplicacion(AplicacionTratamiento a){j.sql("insert into sanidad.aplicaciones_tratamiento(id,empresa_id,tratamiento_detalle_id,fecha_programada,dosis_programada,estado) values(:id,:e,:d,:f,:dp,:s) on conflict do nothing").param("id",a.id()).param("e",a.empresaId()).param("d",a.tratamientoDetalleId()).param("f",ts(a.fechaProgramada())).param("dp",a.dosisProgramada()).param("s",a.estado().name()).update();return a;}public List<AplicacionTratamiento>aplicaciones(UUID t,UUID e){return j.sql("select a.* from sanidad.aplicaciones_tratamiento a join sanidad.tratamiento_detalles d on d.id=a.tratamiento_detalle_id where d.tratamiento_id=:t and a.empresa_id=:e order by fecha_programada").param("t",t).param("e",e).query(this::ma).list();}public Optional<AplicacionTratamiento>aplicacion(UUID id,UUID t,UUID e){return aplicaciones(t,e).stream().filter(a->a.id().equals(id)).findFirst();}
public void activar(UUID id,UUID e,UUID a){j.sql("update sanidad.tratamientos set estado='ACTIVO',updated_at=now(),updated_by=:a,version=version+1 where id=:id and empresa_id=:e and estado in('BORRADOR','SUSPENDIDO')").param("a",a).param("id",id).param("e",e).update();}public void cancelarFuturas(UUID t,UUID e){j.sql("update sanidad.aplicaciones_tratamiento a set estado='CANCELADA',updated_at=now(),version=version+1 from sanidad.tratamiento_detalles d where d.id=a.tratamiento_detalle_id and d.tratamiento_id=:t and a.empresa_id=:e and a.estado in('PENDIENTE','ATRASADA')").param("t",t).param("e",e).update();}
public AplicacionTratamiento aplicar(UUID id,UUID t,UUID e,Instant f,java.math.BigDecimal d,UUID actor,String o,long v){int n=j.sql("update sanidad.aplicaciones_tratamiento a set estado='APLICADA',fecha_aplicada=:f,dosis_aplicada=:d,aplicado_por=:a,observaciones=:o,updated_at=now(),version=version+1 from sanidad.tratamiento_detalles td join sanidad.tratamientos tr on tr.id=td.tratamiento_id where a.tratamiento_detalle_id=td.id and a.id=:id and tr.id=:t and a.empresa_id=:e and tr.estado='ACTIVO' and a.estado in('PENDIENTE','ATRASADA') and a.version=:v").param("f",ts(f)).param("d",d).param("a",actor).param("o",o).param("id",id).param("t",t).param("e",e).param("v",v).update();if(n==0)throw new BusinessException(ErrorCode.VERSION_CONFLICT);return aplicacion(id,t,e).orElseThrow();}public List<AplicacionTratamiento> marcarAtrasadas(UUID e,Instant now){List<AplicacionTratamiento> pendientes=j.sql("select * from sanidad.aplicaciones_tratamiento where empresa_id=:e and estado='PENDIENTE' and fecha_programada<:n for update").param("e",e).param("n",ts(now)).query(this::ma).list();if(!pendientes.isEmpty())j.sql("update sanidad.aplicaciones_tratamiento set estado='ATRASADA',updated_at=now(),version=version+1 where empresa_id=:e and estado='PENDIENTE' and fecha_programada<:n").param("e",e).param("n",ts(now)).update();return pendientes.stream().map(a->new AplicacionTratamiento(a.id(),a.empresaId(),a.tratamientoDetalleId(),a.fechaProgramada(),a.fechaAplicada(),a.dosisProgramada(),a.dosisAplicada(),a.aplicadoPor(),EstadoAplicacionTratamiento.ATRASADA,a.observaciones(),a.version()+1)).toList();}public void finalizar(UUID id,UUID e,UUID a){j.sql("update sanidad.tratamientos set estado='FINALIZADO',fecha_fin_real=now(),updated_at=now(),updated_by=:a,version=version+1 where id=:id and empresa_id=:e and estado='ACTIVO'").param("a",a).param("id",id).param("e",e).update();}
private CasoClinico mc(ResultSet r,int n)throws SQLException{return new CasoClinico(r.getObject("id",UUID.class),r.getObject("empresa_id",UUID.class),r.getObject("animal_id",UUID.class),instant(r,"fecha_inicio"),r.getString("sintomas"),r.getObject("enfermedad_id",UUID.class),r.getString("diagnostico_texto"),SeveridadCaso.valueOf(r.getString("severidad")),EstadoCasoClinico.valueOf(r.getString("estado")),r.getObject("veterinario_id",UUID.class),instant(r,"fecha_cierre"),r.getString("resultado"),r.getString("observaciones"),r.getLong("version"));}private Tratamiento mt(ResultSet r,int n)throws SQLException{return new Tratamiento(r.getObject("id",UUID.class),r.getObject("empresa_id",UUID.class),r.getObject("caso_clinico_id",UUID.class),r.getObject("animal_id",UUID.class),instant(r,"fecha_inicio"),instant(r,"fecha_fin_estimada"),instant(r,"fecha_fin_real"),r.getString("diagnostico"),r.getObject("veterinario_id",UUID.class),EstadoTratamiento.valueOf(r.getString("estado")),r.getString("observaciones"),r.getLong("version"));}private TratamientoDetalle md(ResultSet r,int n)throws SQLException{return new TratamientoDetalle(r.getObject("id",UUID.class),r.getObject("empresa_id",UUID.class),r.getObject("tratamiento_id",UUID.class),r.getObject("producto_id",UUID.class),r.getObject("lote_producto_id",UUID.class),r.getBigDecimal("dosis"),r.getString("unidad_dosis"),r.getInt("frecuencia_horas"),r.getInt("duracion_dias"),r.getString("via_administracion"),r.getInt("retiro_carne_dias"),r.getInt("retiro_leche_dias"));}private AplicacionTratamiento ma(ResultSet r,int n)throws SQLException{return new AplicacionTratamiento(r.getObject("id",UUID.class),r.getObject("empresa_id",UUID.class),r.getObject("tratamiento_detalle_id",UUID.class),instant(r,"fecha_programada"),instant(r,"fecha_aplicada"),r.getBigDecimal("dosis_programada"),r.getBigDecimal("dosis_aplicada"),r.getObject("aplicado_por",UUID.class),EstadoAplicacionTratamiento.valueOf(r.getString("estado")),r.getString("observaciones"),r.getLong("version"));}private static Instant instant(ResultSet r,String c)throws SQLException{OffsetDateTime v=r.getObject(c,OffsetDateTime.class);return v==null?null:v.toInstant();}private static Timestamp ts(Instant i){return i==null?null:Timestamp.from(i);}
}
